defmodule JoobQ.TelemetryTest do
  # Not async: telemetry handlers are global, and other tests run jobs too.
  use ExUnit.Case, async: false

  alias JoobQ.Worker.Outcome

  @events for prefix <- [[:joobq, :job], [:joobq, :enqueue], [:joobq, :workflow]],
              suffix <- [:start, :stop, :exception],
              do: prefix ++ [suffix]

  @job_keys [:attempt, :instance, :jid, :job_type, :queue, :task_kind]

  defmodule Handler do
    def perform(%{payload: %{"do" => "ok"}}), do: {:ok, %{"output" => "OUTPUTSECRET"}}
    def perform(%{payload: %{"do" => "error"}}), do: {:error, :nope}

    def perform(%{payload: %{"do" => "raise"} = payload}),
      do: raise(ArgumentError, inspect(payload))
  end

  def forward(event, measurements, metadata, pid),
    do: send(pid, {:event, event, measurements, metadata})

  setup do
    id = "joobq-test-#{System.unique_integer([:positive])}"
    :ok = :telemetry.attach_many(id, @events, &__MODULE__.forward/4, self())
    on_exit(fn -> :telemetry.detach(id) end)
  end

  defp job(action) do
    payload = %{"do" => action, "password" => "PAYLOADSECRET"}
    secrets = %{lease_token: "LEASESECRET", context: %{"t" => "CONTEXTSECRET"}}

    job = %JoobQ.Job{
      jid: "j-#{action}",
      queue: "mail",
      type: "welcome",
      attempt: 2,
      payload: payload
    }

    Map.merge(job, Map.put(secrets, :instance, MyApp.JoobQ))
  end

  defp received do
    receive do
      {:event, event, measurements, metadata} -> [{event, measurements, metadata} | received()]
    after
