  test "a job's span: start, then stop or exception, with exactly the documented metadata" do
    for action <- ["ok", "error", "raise"], do: Outcome.run(Handler, job(action))
    events = received()

    starts = for {[:joobq, :job, :start], measures, meta} <- events, do: {measures, meta}
    assert length(starts) == 3
    assert Enum.all?(starts, &start?/1)

    stops = for {[:joobq, :job, :stop], measures, meta} <- events, do: {measures, meta}
    assert [{ok_measures, ok}, {_measures, failed}] = stops
    assert Map.has_key?(ok_measures, :duration)

    assert keys(ok) == Enum.sort(@job_keys ++ [:outcome, :retryable, :error_class])
    assert %{outcome: :complete, jid: "j-ok", attempt: 2, queue: "mail", job_type: "welcome"} = ok
    assert %{outcome: :fail, retryable: true, error_class: "error"} = failed

    exceptions = for {[:joobq, :job, :exception], measures, meta} <- events, do: {measures, meta}
    assert [{raised_measures, raised}] = exceptions
    assert Map.has_key?(raised_measures, :duration)

    assert keys(raised) == Enum.sort(@job_keys ++ [:kind, :error_class])
    assert %{kind: :error, error_class: "ArgumentError", jid: "j-raise"} = raised

    for secret <- ["PAYLOADSECRET", "OUTPUTSECRET", "LEASESECRET", "CONTEXTSECRET"] do
      refute inspect(events) =~ secret
    end
  end

  test "an enqueue with a wrong option is an exception event, then the error is raised" do
    assert_raise ArgumentError, fn ->
      payload = %{"password" => "PAYLOADSECRET"}
      JoobQ.enqueue("mail", "welcome", payload, name: :nowhere, delay_ms: -1)
    end

    assert [start, exception] = received()
    assert {[:joobq, :enqueue, :start], _measures, %{instance: :nowhere, queue: "mail"}} = start

    assert {[:joobq, :enqueue, :exception], _measures, failed} = exception
    assert %{kind: :error, error_class: "ArgumentError"} = failed

    refute inspect([start, exception]) =~ "PAYLOADSECRET"
  end

  test "a request that raises is an exception event with its kind and class, never the reason or the stack" do
    id = "joobq-request-#{System.unique_integer([:positive])}"
    :ok = :telemetry.attach(id, [:joobq, :request, :exception], &__MODULE__.forward/4, self())
    on_exit(fn -> :telemetry.detach(id) end)
    metadata = %{name: :nowhere, method: :post, path: "/tasks/:token/heartbeat"}

    assert_raise RuntimeError, fn ->
      JoobQ.Transport.span(metadata, fn -> raise "Bearer TOKENSECRET" end)
    end

    assert_receive {:event, [:joobq, :request, :exception], _measures, failed}
    assert keys(failed) == [:error_class, :kind, :method, :name, :path]
    assert %{kind: :error, error_class: "RuntimeError"} = failed
    refute inspect(failed) =~ "TOKENSECRET"
  end

  test "names in events are bounded: valid UTF-8, no control characters, at most 200 code points" do
    long = String.duplicate("q", 1_000) <> "\e[31m"

    Outcome.run(Handler, %{
      job("ok")
      | queue: long,
        type: "a" <> String.duplicate("\u0301", 100_000)
    })

    assert_raise ArgumentError, fn -> JoobQ.start_workflow(long, nil, name: :nowhere) end
    events = received()

    names =
      for {_event, _measures, meta} <- events,
          key <- [:queue, :job_type, :name],
          is_binary(meta[key]),
          do: meta[key]

    assert names != []
    assert Enum.all?(names, &(String.valid?(&1) and length(String.to_charlist(&1)) <= 200))
    refute Enum.any?(names, &(&1 =~ "\e"))
  end

  defp keys(map), do: map |> Map.keys() |> Enum.sort()

  defp start?({measures, meta}),
    do: Map.has_key?(measures, :system_time) and keys(meta) == @job_keys
end
